`timescale 1ns/1ps
module tb_multipath_memory_fabric; localparam int REQUESTERS=8,PATHS=4,BANKS=8,ADDR_WIDTH=16,DATA_WIDTH=64,QOS_WIDTH=3; logic clk=0; always #5 clk=~clk; logic rst_n,enable; logic [REQUESTERS-1:0] req_valid,req_write,req_grant; logic [REQUESTERS-1:0][ADDR_WIDTH-1:0] req_addr; logic [REQUESTERS-1:0][DATA_WIDTH-1:0] req_wdata; logic [REQUESTERS-1:0][7:0] req_be; logic [REQUESTERS-1:0][QOS_WIDTH-1:0] req_qos; logic [REQUESTERS-1:0][1:0] req_grant_path; logic [REQUESTERS-1:0][2:0] req_grant_bank; logic [PATHS-1:0] path_valid,path_write; logic [PATHS-1:0][2:0] path_bank; logic [PATHS-1:0][ADDR_WIDTH-1:0] path_addr; logic [PATHS-1:0][DATA_WIDTH-1:0] path_wdata; logic [PATHS-1:0][7:0] path_be; logic [PATHS-1:0][QOS_WIDTH-1:0] path_qos; logic busy; logic [2:0] active_paths; multipath_memory_fabric #(.REQUESTERS(REQUESTERS),.PATHS(PATHS),.BANKS(BANKS),.ADDR_WIDTH(ADDR_WIDTH),.DATA_WIDTH(DATA_WIDTH),.QOS_WIDTH(QOS_WIDTH)) dut(.*); initial begin rst_n=0;enable=0;req_valid='0;req_write='0;req_addr='0;req_wdata='0;req_be='0;req_qos='0; repeat(2)@(posedge clk);rst_n=1;enable=1; req_valid[0]=1;req_addr[0]=16'h0000;req_valid[1]=1;req_addr[1]=16'h0040;req_valid[2]=1;req_addr[2]=16'h0080;req_valid[3]=1;req_addr[3]=16'h00c0; #1;if(active_paths!==4)$fatal(1,"Expected 4 parallel paths"); @(posedge clk);req_valid='0; req_valid[0]=1;req_addr[0]=16'h0100;req_valid[1]=1;req_addr[1]=16'h0140;req_valid[2]=1;req_addr[2]=16'h0180; #1;if(active_paths!==1)$fatal(1,"Expected bank conflict serialization");$display("PASS multipath");$finish;end endmodule
